// Ignore delivery/read status callbacks; keep only real customer messages
const out = [];
for (const { json: j } of $input.all()) {
  const v = j.value || j.entry?.[0]?.changes?.[0]?.value || j;
  for (const m of v.messages || []) {
    const contact = (v.contacts || []).find(c => c.wa_id === m.from) || {};
    const media = m.image || (m.document && /image/i.test(m.document.mime_type || '') ? m.document : null);
    out.push({ json: { source: 'whatsapp', phone: m.from, name: contact.profile?.name || 'there',
      message_type: m.type, text: m.text?.body || m.image?.caption || '', media_id: media?.id || '',
      has_bill_photo: !!media, received_at: new Date(Number(m.timestamp) * 1000 || Date.now()).toISOString() } });
  }
}
return out;

const f = $json;
const bin = $input.item.binary || {};
const key = Object.keys(bin)[0];
let phone = String(f['WhatsApp Number'] || '').replace(/\D/g, '');
if (phone.length === 10) phone = '91' + phone;
return { json: { source: 'web_form', phone, name: f['Full Name'], city: f['City'], property_type: f['Property Type'],
  roof_sqft: Number(f['Shadow-free Roof Area (sq ft)']) || null, received_at: new Date().toISOString() },
  binary: key ? { bill: bin[key] } : {} };

// Works for both entry paths (each trigger is its own execution)
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary || {};
  const key = Object.keys(bin)[0];
  if (!key) continue;
  const lead = $('Parse WhatsApp Message').isExecuted ? $('Parse WhatsApp Message').all()[i]?.json || $('Parse WhatsApp Message').first().json : items[i].json;
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  const mime = bin[key].mimeType || 'image/jpeg';
  const lead_id = `SOL-${$now.setZone('Asia/Kolkata').toFormat('yyMMdd')}-${String(lead.phone).slice(-4)}-${Math.random().toString(36).slice(2, 5).toUpperCase()}`;
  out.push({ json: { ...lead, lead_id, vision_body: {
    model: 'gpt-4o', temperature: 0, response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: `You are an OCR engine for Indian electricity bills (all DISCOMs, any language). Read the bill image and return ONLY JSON:
{"legible": boolean, "consumer_name": string|null, "consumer_number": string|null, "discom": string|null, "state": string|null, "city": string|null, "pincode": string|null, "address": string|null,
 "tariff_category": "residential"|"commercial"|"industrial"|"agricultural"|null, "sanctioned_load_kw": number|null, "connection_phase": "single"|"three"|null,
 "billing_period_months": number (1 for monthly, 2 for bi-monthly), "units_consumed": number|null, "bill_amount": number|null, "energy_charges": number|null, "fixed_charges": number|null,
 "monthly_history": [{"month": string, "units": number}] (the consumption-history table if printed, else []),
 "confidence": number (0-1), "issues": [string]}
Convert kVA to kW at 0.9 if only kVA is given. Never guess numbers you cannot read: use null and add the reason to issues.` },
      { role: 'user', content: [{ type: 'text', text: 'Read this electricity bill.' },
        { type: 'image_url', image_url: { url: `data:${mime};base64,${buf.toString('base64')}`, detail: 'high' } }] } ] } },
    binary: { bill: bin[key] } });
}
return out;

const lead = $('Prepare Lead & OCR Request').item.json;
let o = {};
try { o = JSON.parse($json.choices?.[0]?.message?.content || '{}'); } catch (e) { o = { legible: false, issues: ['OCR response not JSON'] }; }
const months = Math.max(1, Number(o.billing_period_months) || 1);
const hist = (o.monthly_history || []).map(h => Number(h.units)).filter(u => u > 0);
// bi-monthly histories are per bill – normalise to per month
const histMonthly = hist.map(u => u / months);
const monthly_units = histMonthly.length >= 3 ? histMonthly.reduce((a, b) => a + b, 0) / histMonthly.length
  : (Number(o.units_consumed) > 0 ? Number(o.units_consumed) / months : 0);
const peak_month_units = histMonthly.length ? Math.max(...histMonthly) : monthly_units;
const ok = o.legible !== false && monthly_units >= 30 && (o.confidence ?? 1) >= 0.5;
const prop = (lead.property_type || '').toLowerCase();
return { json: { ...lead, ocr: o, readable: ok,
  ocr_issue: ok ? '' : (o.issues || []).join('; ') || 'units not readable',
  monthly_units: Math.round(monthly_units), peak_month_units: Math.round(peak_month_units), history_points: histMonthly.length,
  state: o.state || '', city: lead.city || o.city || '', discom: o.discom || '',
  segment: prop.includes('society') ? 'housing_society' : prop.includes('commercial') || /commercial|industrial/.test(o.tariff_category || '') ? 'commercial' : 'residential' } };

const L = $json;
const CFG = {
  company: 'Your Solar EPC Pvt Ltd', company_phone: '+91 9XXXXXXXXX', company_web: 'https://yoursolar.example.com', gst_pct: 8.9,
  panel_w: 545, sqft_per_kw: 100, offset_target: 1.0, min_kw: 1,
  // specific yield kWh per kWp per year
  yield_by_state: { gujarat: 1550, rajasthan: 1580, telangana: 1450, 'andhra pradesh': 1450, karnataka: 1450, maharashtra: 1450,
    'madhya pradesh': 1480, 'tamil nadu': 1450, delhi: 1400, haryana: 1400, punjab: 1400, 'uttar pradesh': 1400, chhattisgarh: 1430,
    'west bengal': 1300, bihar: 1330, odisha: 1350, jharkhand: 1350, kerala: 1350, goa: 1400, assam: 1250, uttarakhand: 1300,
    'himachal pradesh': 1300, 'jammu and kashmir': 1350 },
  default_yield: 1400,
  special_category: ['assam', 'arunachal pradesh', 'manipur', 'meghalaya', 'mizoram', 'nagaland', 'sikkim', 'tripura',
    'himachal pradesh', 'uttarakhand', 'jammu and kashmir', 'ladakh', 'andaman and nicobar islands', 'lakshadweep'],
  // turnkey price ₹/kW (incl. GST) by size band
  price_bands: [[3, 62000], [10, 55000], [100, 50000], [Infinity, 45000]],
  export_rate: 3.0, tariff_escalation: 0.03, degradation: 0.005, default_tariff: 7.5,
  loan_rate: 0.07, loan_years: 10, co2_kg_per_kwh: 0.82,
  survey_link: 'https://cal.com/REPLACE_WITH_YOUR_TEAM/solar-site-survey'
};
const r0 = x => Math.round(x), r1 = x => Math.round(x * 10) / 10, r2 = x => Math.round(x * 100) / 100;
const st = String(L.state || '').toLowerCase().trim();
const yld = CFG.yield_by_state[st] || CFG.default_yield;
const special = CFG.special_category.includes(st);
const annual_units = L.monthly_units * 12;

// ---- sizing ----
let kw = Math.max(CFG.min_kw, annual_units * CFG.offset_target / yld);
const caps = [];
const sl = Number(L.ocr?.sanctioned_load_kw);
if (sl > 0 && kw > sl) { kw = sl; caps.push(`capped at sanctioned load ${sl} kW (net-metering limit)`); }
if (L.roof_sqft && kw > L.roof_sqft / CFG.sqft_per_kw) { kw = L.roof_sqft / CFG.sqft_per_kw; caps.push(`limited by roof area ${L.roof_sqft} sq ft`); }
const panels = Math.max(2, Math.ceil(kw * 1000 / CFG.panel_w));
const system_kw = r2(panels * CFG.panel_w / 1000);
const inverter_kw = system_kw <= 3 ? Math.ceil(system_kw) : Math.ceil(system_kw * 0.9);
const phase = system_kw > 5 || L.ocr?.connection_phase === 'three' ? 'Three-phase' : 'Single-phase';

// ---- cost & subsidy ----
const rate_kw = CFG.price_bands.find(([lim]) => system_kw <= lim)[1];
const gross_cost = r0(system_kw * rate_kw);
let subsidy = 0;
if (L.segment === 'residential') {
  const [a, b, cap] = special ? [33000, 19800, 85800] : [30000, 18000, 78000];
  subsidy = system_kw <= 2 ? a * system_kw : system_kw < 3 ? 2 * a + b * (system_kw - 2) : cap;
  subsidy = Math.min(r0(subsidy), cap);
} else if (L.segment === 'housing_society') {
  subsidy = r0(18000 * Math.min(system_kw, 500));
}
const net_cost = gross_cost - subsidy;

// ---- tariff & ROI (25 years) ----
const units = Number(L.ocr?.units_consumed) || L.monthly_units * (L.ocr?.billing_period_months || 1);
let tariff = Number(L.ocr?.energy_charges) > 0 && units ? L.ocr.energy_charges / units
  : Number(L.ocr?.bill_amount) > 0 && units ? (L.ocr.bill_amount - (Number(L.ocr.fixed_charges) || 0)) / units : CFG.default_tariff;
tariff = Math.min(15, Math.max(3, tariff));
const gen_y1 = system_kw * yld;
let cum = 0, payback = null; const cumSeries = [];
let save_y1 = 0, total25 = 0;
for (let y = 1; y <= 25; y++) {
  const gen = gen_y1 * Math.pow(1 - CFG.degradation, y - 1);
  const self = Math.min(gen, annual_units), exp = Math.max(0, gen - annual_units);
  const s = self * tariff * Math.pow(1 + CFG.tariff_escalation, y - 1) + exp * CFG.export_rate;
  if (y === 1) save_y1 = s;
  total25 += s; cum += s; cumSeries.push(r0(cum));
  if (payback === null && cum >= net_cost) payback = r1(y - 1 + (net_cost - (cum - s)) / s);
}
const monthly_bill_now = Number(L.ocr?.bill_amount) ? r0(L.ocr.bill_amount / (L.ocr.billing_period_months || 1)) : r0(L.monthly_units * tariff);
const monthly_savings = r0(save_y1 / 12);
const bill_after = Math.max(r0((Number(L.ocr?.fixed_charges) || 0) / (L.ocr?.billing_period_months || 1)), monthly_bill_now - monthly_savings);
const i = CFG.loan_rate / 12, n = CFG.loan_years * 12;
const emi = r0(net_cost * i * Math.pow(1 + i, n) / (Math.pow(1 + i, n) - 1));
const co2_t_year = r1(gen_y1 * CFG.co2_kg_per_kwh / 1000);
const trees = r0(gen_y1 * CFG.co2_kg_per_kwh / 22);

// ---- lead score ----
const score = (L.segment === 'commercial' && system_kw >= 10) || (L.segment !== 'commercial' && system_kw >= 3 && monthly_bill_now >= 2500) ? 'HOT'
  : system_kw >= 2 ? 'WARM' : 'NURTURE';

// savings chart (QuickChart) – cumulative savings vs net cost
const chart = { type: 'line', data: { labels: Array.from({ length: 25 }, (_, k) => 'Y' + (k + 1)), datasets: [
  { label: 'Cumulative savings (₹)', data: cumSeries, borderColor: '#f39c12', backgroundColor: 'rgba(243,156,18,0.15)', fill: true },
  { label: 'Your net investment (₹)', data: cumSeries.map(() => net_cost), borderColor: '#17344d', borderDash: [6, 4], fill: false } ] },
  options: { legend: { position: 'bottom' }, scales: { yAxes: [{ ticks: { beginAtZero: true } }] } } };

return { json: { ...L, cfg: CFG, calc: {
  yield_kwh_per_kwp: yld, special_category_state: special, annual_units, system_kw, panels, panel_w: CFG.panel_w, inverter_kw, phase,
  roof_needed_sqft: r0(system_kw * CFG.sqft_per_kw), caps, rate_per_kw: rate_kw, gross_cost, subsidy, net_cost,
  tariff: r2(tariff), gen_y1: r0(gen_y1), gen_monthly: r0(gen_y1 / 12), offset_pct: r0(Math.min(100, gen_y1 / annual_units * 100)),
  monthly_bill_now, monthly_savings, bill_after, savings_y1: r0(save_y1), savings_25y: r0(total25),
  payback_years: payback ?? '>25', roi_pct: r0((total25 - net_cost) / net_cost * 100), emi, loan_years: CFG.loan_years,
  co2_t_year, trees, lead_score: score,
  chart_url: 'https://quickchart.io/chart?w=700&h=320&bkg=white&c=' + encodeURIComponent(JSON.stringify(chart)) } } };

const L = $('Size System, Subsidy & ROI').item.json;
const ai = $json.message?.content || {};
const c = L.calc, cfg = L.cfg;
const inr = v => '₹' + Number(v).toLocaleString('en-IN');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const row = (k, v) => `<tr><td>${k}</td><td><b>${v}</b></td></tr>`;
const html = `<!doctype html><html><head><meta charset="utf-8"><title>Solar Proposal ${L.lead_id}</title><style>
@page{size:A4;margin:14mm}body{font-family:Arial,Helvetica,sans-serif;color:#1d2733;font-size:12px}
.hero{background:linear-gradient(135deg,#f39c12,#e67e22);color:#fff;padding:18px 22px;border-radius:10px}
.hero h1{margin:0 0 6px;font-size:22px}.kpis{display:flex;gap:10px;margin:14px 0}.kpi{flex:1;background:#fff7ec;border:1px solid #f5c98a;border-radius:8px;padding:10px;text-align:center}
.kpi b{display:block;font-size:18px;color:#c0620b}h2{font-size:15px;border-bottom:2px solid #f39c12;padding-bottom:4px;margin-top:18px}
table{width:100%;border-collapse:collapse}td{padding:6px 8px;border-bottom:1px solid #eee}.two{display:flex;gap:16px}.two>div{flex:1}
.note{color:#667;font-size:10px}.cta{background:#17344d;color:#fff;padding:12px 16px;border-radius:8px;margin-top:14px}</style></head><body>
<div class="hero"><h1>${esc(ai.headline || `${c.system_kw} kWp Rooftop Solar Proposal`)}</h1>
Prepared for <b>${esc(L.ocr?.consumer_name || L.name)}</b> · ${esc(L.city)} ${esc(L.state)} · ${esc(L.discom)} · Ref ${L.lead_id} · ${$now.setZone('Asia/Kolkata').toFormat('dd LLL yyyy')}</div>
<p>${esc(ai.intro)}</p>
<div class="kpis"><div class="kpi"><b>${c.system_kw} kWp</b>System size</div><div class="kpi"><b>${inr(c.subsidy)}</b>PM Surya Ghar subsidy</div>
<div class="kpi"><b>${inr(c.monthly_savings)}/mo</b>Estimated saving</div><div class="kpi"><b>${c.payback_years} yrs</b>Payback</div></div>
<div class="two"><div><h2>Your bill today</h2><table>
${row('Average monthly consumption', c.annual_units / 12 + ' units')}${row('Peak month', L.peak_month_units + ' units')}
${row('Effective tariff', inr(c.tariff) + '/unit')}${row('Current monthly bill (avg)', inr(c.monthly_bill_now))}
${row('Estimated bill after solar', inr(c.bill_after))}${row('Sanctioned load', (L.ocr?.sanctioned_load_kw ?? '–') + ' kW')}</table></div>
<div><h2>Recommended system</h2><table>
${row('Solar modules', `${c.panels} × ${c.panel_w} Wp (mono PERC / TOPCon)`)}${row('Inverter', `${c.inverter_kw} kW ${c.phase} on-grid`)}
${row('Roof area needed', c.roof_needed_sqft + ' sq ft shadow-free')}${row('Generation', c.gen_monthly + ' units/month (' + c.offset_pct + '% of usage)')}
${row('Specific yield used', c.yield_kwh_per_kwp + ' kWh/kWp/yr')}${c.caps.length ? row('Note', esc(c.caps.join('; '))) : ''}</table></div></div>
<div class="two"><div><h2>Investment</h2><table>
${row('System cost (turnkey, incl. GST)', inr(c.gross_cost))}${row('Less: central subsidy', '– ' + inr(c.subsidy))}
${row('Net investment', inr(c.net_cost))}${row(`EMI option (${c.loan_years} yrs @ 7%)`, inr(c.emi) + '/month')}</table></div>
<div><h2>Returns (25 years)</h2><table>
${row('Year-1 savings', inr(c.savings_y1))}${row('25-year savings', inr(c.savings_25y))}${row('Return on investment', c.roi_pct + '%')}
${row('CO₂ avoided', c.co2_t_year + ' t/year ≈ ' + c.trees + ' trees')}</table></div></div>
<h2>Savings vs investment</h2><img src="${c.chart_url}" style="width:100%">
<h2>Why go solar now</h2><ul>${(ai.why_now || []).map(x => `<li>${esc(x)}</li>`).join('')}</ul>
<h2>FAQs</h2>${(ai.faqs || []).map(f => `<p><b>${esc(f.q)}</b><br>${esc(f.a)}</p>`).join('')}
<div class="cta"><b>Next step: a free site survey (30 min).</b> Book here: ${cfg.survey_link}<br>${esc(cfg.company)} · ${cfg.company_phone} · ${cfg.company_web}</div>
<p class="note">Estimates are based on your bill, the regional solar yield, ${inr(c.tariff)}/unit with 3%/yr tariff escalation, 0.5%/yr degradation and a ₹${cfg.export_rate}/unit export rate. The subsidy follows the PM Surya Ghar Muft Bijli Yojana norms for residential consumers and is subject to DISCOM/MNRE approval and the current notification. The final price depends on the site survey.</p>
</body></html>`;
return { json: { html, file_name: `Solar_Proposal_${L.lead_id}.pdf`, ai } };

